-- Marketing Studio: Kling O3 Pro reference-to-video also serves the `marketing` feature, still disabled (an Admin switches it on in Settings). The fal input schema (read 2026-10-24)
-- takes image_urls as a free-length list of reference images that the prompt addresses as @Image1, @Image2 and so on; its 4-image limit applies only together with a video input, and the app's max_images stays 4.
UPDATE "model_configs" SET "features" = array_append("features", 'marketing'), "sources" = "sources" || '{"referenceImages":{"url":"https://fal.ai/api/openapi/queue/openapi.json?endpoint_id=fal-ai/kling-video/o3/pro/reference-to-video","readAt":"2026-10-24","note":"image_urls is a list the prompt addresses as @Image1, @Image2; the app sends the model photo and the product photo"}}'::jsonb WHERE "id" = 'kling-o3-pro' AND NOT 'marketing' = ANY("features");
